{"task": {"current_case": {"facts": "Alice has a son, Bob, who satisfies section 152(c)(1) for the year 2015. Bob has a son, Charlie, who satisfies section 152(c)(1) for the year 2015.", "question": "Section 152(b)(1) applies to Bob for the year 2015."}, "unchanged_legal_program": {"input_fields_json": "{"query_person":{"type":"string","description":"被查询个人。"},"query_year":{"type":"integer","description":"被查询个人纳税年度开始所在的公历年。"},"qualifying_child_records":{"type":"array|null","description":"已解析的有向明确给定；每个对象严格为 {individual:string,taxpayer:string,taxpayer_year:integer}，表示 individual 是 taxpayer 在其开始于 taxpayer_year 的纳税年度的 qualifying child。null 表示该事实通道未读取或未解析；[] 表示已解析且无记录。"},"qualifying_relative_records":{"type":"array|null","description":"已解析的有向明确给定；每个对象严格为 {individual:string,taxpayer:string,taxpayer_year:integer}，表示 individual 是 taxpayer 在其开始于 taxpayer_year 的纳税年度的 qualifying relative。null 表示该事实通道未读取或未解析；[] 表示已解析且无记录。"}}", "name": "dependent_disqualification", "program": "def apply(inputs,premises):
    person=inputs.get('query_person')
    year=inputs.get('query_year')
    if not isinstance(person,str) or type(year) is not int:
        return {'handled':False,'answer':None}
    child=inputs.get('qualifying_child_records')
    relative=inputs.get('qualifying_relative_records')
    for records in (child,relative):
        if records is None:
            continue
        if not isinstance(records,list):
            raise TypeError('Dependency records must be arrays or null')
        for record in records:
            if not isinstance(record,dict):
                raise TypeError('Each dependency record must be an object')
            individual=record.get('individual')
            taxpayer=record.get('taxpayer')
            record_year=record.get('taxpayer_year')
            if not isinstance(individual,str) or not isinstance(taxpayer,str) or type(record_year) is not int:
                raise ValueError('Malformed dependency record')
            if individual==person and record_year==year:
                return {'handled':True,'answer':'Entailment'}
    if child is None or relative is None:
        return {'handled':False,'answer':None}
    return {'handled':True,'answer':'Contradiction'}", "query_clause": "152(b)(1)", "scope": "exact_clause", "source_quote": "If an individual is a dependent of a taxpayer for any taxable year of such taxpayer beginning in a calendar year, such individual shall be treated as having no dependents for any taxable year of such individual beginning in such calendar year."}}, "output_schema": {"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["query_person", "query_year", "qualifying_child_resolution", "qualifying_child_records", "qualifying_relative_resolution", "qualifying_relative_records", "witnesses", "unresolved"], "properties": {"query_person": {"type": "string", "minLength": 1}, "query_year": {"type": "integer"}, "qualifying_child_resolution": {"enum": ["resolved", "unknown"]}, "qualifying_child_records": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["individual", "taxpayer", "taxpayer_year"], "properties": {"individual": {"type": "string", "minLength": 1}, "taxpayer": {"type": "string", "minLength": 1}, "taxpayer_year": {"type": "integer"}}}}, "qualifying_relative_resolution": {"enum": ["resolved", "unknown"]}, "qualifying_relative_records": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["individual", "taxpayer", "taxpayer_year"], "properties": {"individual": {"type": "string", "minLength": 1}, "taxpayer": {"type": "string", "minLength": 1}, "taxpayer_year": {"type": "integer"}}}}, "witnesses": {"type": "array", "minItems": 1, "items": {"type": "object", "additionalProperties": false, "required": ["field", "quote"], "properties": {"field": {"enum": ["facts", "question"]}, "quote": {"type": "string", "minLength": 1}}}}, "unresolved": {"type": "array", "items": {"type": "string", "minLength": 1}}}}}
